# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Hyperparameters
NUM_SPECIES = 206
MAX_EPOCHS = 40
EARLY_STOPPING_PATIENCE = 5

# Data loading
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader, val_loader = build_train_val_dataloaders(
    metadata_csv=METADATA_FILE,
    audio_dir=DATA_DIR,
    batch_size=32,
    augment=True,
    val_split=0.2,
)

# Model definition
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species):
        super(BirdCLEFModel, self).__init__()
        self.conv_layers = nn.Sequential(
            nn.Conv2d(1, 64, 3, padding=1), nn.BatchNorm2d(64), nn.ReLU(),
            nn.Conv2d(64, 128, 3, padding=1), nn.BatchNorm2d(128), nn.ReLU(),
        )
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(128, 256), nn.ReLU(), nn.Dropout(0.5),
            nn.Linear(256, num_species)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Training loop
def train_model(model, train_loader, val_loader, epochs, batch_size, learning_rate, device):
    model.to(device)
    criterion = nn.BCELoss()
    optimizer = optim.Adam(model.parameters(), lr=learning_rate, weight_decay=1e-4)

    best_auc = 0.0
    patience = EARLY_STOPPING_PATIENCE

    for epoch in range(epochs):
        model.train()
        running_loss = 0.0
        for inputs, labels in tqdm(train_loader, desc=f"Epoch {epoch+1}/{epochs}"):
            try:
                inputs, labels = inputs.to(device), labels.to(device)
                
                # Apply SpecAugment
                freq_mask = nn.Dropout2d(p=0.2)
                time_mask = nn.Dropout2d(p=0.2)
                inputs = freq_mask(inputs).permute(0, 3, 1, 2)  # (B, C, H, W)
                inputs = time_mask(inputs).permute(0, 2, 3, 1)  # (B, H, W, C)

                optimizer.zero_grad()
                outputs = model(inputs)
                loss = criterion(outputs, labels.float())
                loss.backward()
                optimizer.step()

                running_loss += loss.item()
                torch.cuda.empty_cache()
            except RuntimeError as e:
                if 'out of memory' in str(e):
                    print(f"OOM encountered. Reducing batch size to {batch_size//2}")
                    torch.cuda.empty_cache()
                    break

        # Validation
        model.eval()
        all_preds = []
        all_labels = []
        with torch.no_grad():
            for inputs, labels in val_loader:
                inputs, labels = inputs.to(device), labels.to(device)
                outputs = model(inputs)
                preds = (outputs > 0.5).float().cpu().numpy()
                all_preds.extend(preds)
                all_labels.extend(labels.cpu().numpy())

        # Calculate AUC
        auc = roc_auc_score(all_labels, all_preds, average='weighted')
        print(f"Epoch {epoch+1}/{epochs} - Train Loss: {running_loss/len(train_loader):.4f}, Val AUC: {auc:.4f}")

        # Early Stopping
        if auc > best_auc:
            best_auc = auc
            patience = EARLY_STOPPING_PATIENCE
            torch.save(model.state_dict(), 'model.pt')
        else:
            patience -= 1
            if patience == 0:
                print(f"Early stopping at epoch {epoch+1}")
                break

    return running_loss/len(train_loader), best_auc, model.num_parameters()

# Training and evaluation
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model = BirdCLEFModel(NUM_SPECIES)

training_samples = len(train_loader.dataset)
eval_samples = len(val_loader.dataset)
batch_size = 32
learning_rate = 0.001

final_train_loss, final_auc, num_params = train_model(model, train_loader, val_loader, MAX_EPOCHS, batch_size, learning_rate, device)

# Save metrics to JSON
metrics = {
    "final_train_loss": final_train_loss,
    "final_auc": final_auc,
    "num_params": num_params.item(),
    "epochs_trained": MAX_EPOCHS if patience != 0 else MAX_EPOCHS - EARLY_STOPPING_PATIENCE + 1,
    "batch_size": batch_size,
    "training_samples": training_samples,
    "eval_samples": eval_samples
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))